head.script:
scwin.onpageload = function() {
	var data1 = [
		{ "value": "13" },
		{ "value": "51" },
		{ "value": "28" },
		{ "value": "36" },
		{ "value": "45" },
		{ "value": "15" },
		{ "value": "64" },
		{ "value": "47" },
		{ "value": "49" },
		{ "value": "91" }
	];
	dataList2.setJSON(data1, false);
	fwGaugeChart3.draw();
	fwGaugeChart3.setValue("13");
	var jsonData = {
		"data": [
			{ "value": "490000", "label": "China" },
			{ "value": "340000", "label": "USA" },
			{ "value": "160000", "label": "Brazil" },
			{ "value": "220000", "label": "Spain" },
			{ "value": "123000", "label": "India" }
		]
	};
	var options = {
		caption: "전세계 판매량 요약",
		subCaption: "2006년 동안",
		yAxisName: " 금액 ",
		xAxisName: " 나라 ",
		numberPrefix: "$"
	};
	chartBar1.setChartAttribute(options);
	chartBar1.addTrendLine({
		startValue: "440000",
		color: "1D8BD1",
		displayValue: "최대임계치"
	});
	chartBar1.addTrendLine({
		startValue: "220000",
		color: "FF0000",
		displayValue: "최소임계치"
	});
	chartBar1.applyStyle("font", "captionFont", {
		color: "2a5900",
		size: "20",
		bold: "1",
		underline: "0"
	}, ["Caption"]);
	chartBar1.setJSONData(jsonData);
};
